#!/bin/sh
# Regenerates internal/render/assets/cilium.yaml, the Cilium manifest that
# `hydra cluster render` embeds in each cluster's ClusterResourceSet ConfigMap.
#
# Run it when CILIUM_VERSION changes; never edit the output by hand. The values
# reproduce what `cilium install` produced on hydra-mgmt (cluster-pool IPAM,
# VXLAN tunnel, kube-proxy kept, one operator replica), with one deliberate
# difference: Hubble's TLS certificates are issued in the cluster by Cilium's
# certgen CronJob instead of being generated by Helm. Helm-generated certs
# would put a private key into every rendered manifest and make the output
# differ on every run.
#
# The per-cluster values are rendered as sentinels and substituted by the CLI:
#   hydra-sentinel-cluster   cluster.name (also in Hubble certificate names)
#   10.255.254.0/24          the pod CIDR
#   65000                    the MTU
# A sentinel that survives into the output is caught by the render tests.
set -eu

CILIUM_VERSION=${CILIUM_VERSION:-1.19.1}
HELM=${HELM:-helm}
out=$(dirname "$0")/../internal/render/assets/cilium.yaml

"$HELM" repo add cilium https://helm.cilium.io >/dev/null 2>&1 || true
"$HELM" repo update cilium >/dev/null

{
  printf '# Code generated by hack/gen-cilium.sh from cilium/cilium %s. DO NOT EDIT.\n' "$CILIUM_VERSION"
  "$HELM" template cilium cilium/cilium --version "$CILIUM_VERSION" \
    --namespace kube-system \
    --set cluster.name=hydra-sentinel-cluster \
    --set cluster.id=0 \
    --set ipam.mode=cluster-pool \
    --set 'ipam.operator.clusterPoolIPv4PodCIDRList[0]=10.255.254.0/24' \
    --set MTU=65000 \
    --set kubeProxyReplacement=false \
    --set routingMode=tunnel \
    --set tunnelProtocol=vxlan \
    --set operator.replicas=1 \
    --set hubble.tls.auto.method=cronJob
} > "$out"

echo "wrote $out ($(wc -c < "$out") bytes)"
